import { test, expect } from '@playwright/test';

test.describe('Home Page Navigation - A/B Testing Example', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should navigate from home page to A/B Testing example page and back', async ({ page }) => {
    // Verify welcome heading is visible on home page
    const welcomeHeading = page.getByRole('heading', { name: /welcome to the-internet/i });
    await expect(welcomeHeading).toBeVisible();

    // Verify available examples heading is visible
    const availableExamplesHeading = page.getByRole('heading', { name: /available examples/i });
    await expect(availableExamplesHeading).toBeVisible();

    // Click the A/B Testing link
    const abTestingLink = page.getByRole('link', { name: /a/i });
    await abTestingLink.click();

    // Verify navigation to A/B Testing page
    const abTestingPageHeading = page.getByRole('heading', { name: /a/i });
    await expect(abTestingPageHeading).toBeVisible();

    // Verify URL contains '/abtest'
    const url = page.url();
    expect(url).toContain('/abtest');

    // Verify A/B Testing page content is visible
    const abTestingContent = page.getByText(/a/i);
    await expect(abTestingContent).toBeVisible();

    // Navigate back to home page
    const backButton = page.getByRole('button', { name: /back/i });
    await backButton.click();

    // Verify welcome heading is visible again
    await expect(welcomeHeading).toBeVisible();

    // Verify available examples heading is visible again
    await expect(availableExamplesHeading).toBeVisible();

    // Verify URL is back to root
    const rootUrl = page.url();
    expect(rootUrl).toBe('/');
  });

  test('should handle navigation to A/B Testing page with invalid link', async ({ page }) => {
    // Verify welcome heading is visible on home page
    const welcomeHeading = page.getByRole('heading', { name: /welcome to the-internet/i });
    await expect(welcomeHeading).toBeVisible();

    // Click a non-existent link
    const invalidLink = page.getByRole('link', { name: /invalid/i });
    await invalidLink.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/page not found/i);
    await expect(errorMessage).toBeVisible();

    // Verify welcome heading is still visible
    await expect(welcomeHeading).toBeVisible();

    // Verify available examples heading is still visible
    const availableExamplesHeading = page.getByRole('heading', { name: /available examples/i });
    await expect(availableExamplesHeading).toBeVisible();

    // Verify URL is still root
    const rootUrl = page.url();
    expect(rootUrl).toBe('/');
  });
});
